<?php $commissionSection=$modulePageData['commissions'];if($commissionSection!==null): ?>
<section class="business-overview outstanding-section" id="accounts-commissions" data-outstanding-commissions>
    <div class="section-heading"><div><h2>Comisiones por pagar</h2><p class="section-subtitle">Comisiones netas generadas, menos pagos al vendedor. Separadas de las deudas con proveedores.</p></div></div>
    <div class="outstanding-totals"><?php foreach($commissionSection['currencies'] as $code=>$amount): ?><article class="overview-card"><span class="overview-label"><?= authEscape($code) ?></span><strong><?= authEscape($amount.' '.$code) ?></strong><p>Comisiones pendientes de pago</p></article><?php endforeach; ?></div>
    <div class="contact-table-wrap"><table class="contact-table"><thead><tr><th>Vendedor</th><th>Factura</th><th>Cliente</th><th>Generada neta</th><th>Pagada al vendedor</th><th>Pendiente</th></tr></thead><tbody>
        <?php foreach($commissionSection['rows'] as $commission): ?><tr data-outstanding-commission="<?= (int)$commission['id'] ?>"><td><?= authEscape($commission['seller_name']) ?></td><td><a class="contact-name" href="../ventas/comisiones.php?id=<?= (int)$commission['id'] ?>"><?= authEscape($commission['name']) ?></a></td><td><?= authEscape($commission['customer_name']) ?></td><?php foreach(['commission_generated','commission_paid','commission_pending'] as $key): ?><td class="quotation-money"><?= authEscape($commission[$key].' '.$commission['currency_code']) ?></td><?php endforeach; ?></tr><?php endforeach; ?>
        <?php if(!$commissionSection['rows']): ?><tr><td colspan="6" class="contact-empty">No hay comisiones pendientes con estos filtros.</td></tr><?php endif; ?>
    </tbody></table></div>
    <?php if($commissionSection['pages']>1): ?><nav class="contact-pagination"><span>Página <?= $commissionSection['page'] ?> de <?= $commissionSection['pages'] ?></span><?php foreach(['Anterior'=>$commissionSection['page']-1,'Siguiente'=>$commissionSection['page']+1] as $label=>$number): if($number<1||$number>$commissionSection['pages'])continue; ?><a class="contact-button" href="cuentas-pendientes.php?<?= authEscape(http_build_query(array_replace($modulePageData['filters'],['commissions_page'=>$number]))) ?>#accounts-commissions"><?= $label ?></a><?php endforeach; ?></nav><?php endif; ?>
</section>
<?php endif; ?>
